import { para } from "@paradoc/core";
import type { Form } from "@paradoc/types";

/**
 * The engagement letter artifact this package's prose document composes.
 *
 * Sample material, like the rest of `./examples`. Its purpose is evidence, and
 * the evidence is the opposite of the priced samples'. The proposal, the
 * purchase order and the invoice are all a masthead over a table: what
 * paginates is rows, and a row is a small keep of a predictable height. A
 * letter has no table at all. It is numbered clauses of running prose, each of
 * which is one keep tall enough that where it lands decides where the page
 * breaks, and it ends in two signing blocks that must not be split from the
 * clause above them. That is the case the components are otherwise never asked.
 *
 * It carries no `defs`. Nothing on a letter is computed: the fee basis is a
 * sentence and the retainer is a figure the parties agreed, so there is no
 * arithmetic for the expression language to do and none is invented to give it
 * some.
 *
 * The layer is the seal target. It declares a flow-placed signature slot per
 * party, and the renderer registered for it draws the marker for each slot
 * where the `Signature` block for that party sits. Nothing else describes where
 * a signature goes. `engagement-letter-seal.ts` is the wiring, which is the
 * same shape the proposal's is.
 */

/** The layer that names the composition, and the layer the seal targets. */
export const ENGAGEMENT_LETTER_REACT_LAYER = "composition";

/**
 * The composition module the React layer points at, as the layer declares it.
 *
 * Relative to the artifact file that declares it, which is this one, so it names
 * the sibling module and nothing more. The string is the key a consumer binds
 * the component under, so it is exported rather than written twice.
 */
export const ENGAGEMENT_LETTER_REACT_LAYER_PATH = "engagement-letter-document.tsx";

/**
 * The artifact's signature slots, by the party role each one binds to. A slot
 * names its role, so the seal puts each marker on the `Signature` block for that
 * role without anything mapping the two.
 */
export const ENGAGEMENT_LETTER_SIGNATURE_SLOTS = {
  firm: "firm-signature",
  client: "client-signature",
} as const satisfies Record<string, string>;

/** The engagement letter, exactly as authored. Kept beside the instance for evaluators that take a raw `Form`. */
export const engagementLetterSpec = {
  $schema: "https://schema.paradoc.dev/schema.json",
  kind: "form",
  name: "engagement-letter",
  version: "1.0.0",
  title: "Engagement Letter",
  description:
    "A letter engaging a firm to act for a client: the scope of services as numbered clauses, the fees, the term and how it ends, the governing law, and a signature from each party.",
  metadata: {
    domain: "professional-services",
  },
  parties: {
    firm: {
      label: "Firm",
      description: "The firm agreeing to act.",
      partyType: "organization",
      min: 1,
      max: 1,
      signature: { required: true, witnesses: 0, notarized: false },
    },
    client: {
      label: "Client",
      description: "The organization the firm acts for.",
      partyType: "organization",
      min: 1,
      max: 1,
      signature: { required: true, witnesses: 0, notarized: false },
    },
  },
  fields: {
    reference: {
      type: "text",
      label: "Our reference",
      description: "Identifier the firm files this engagement under.",
      maxLength: 40,
      required: true,
      visible: true,
    },
    effectiveDate: {
      type: "date",
      label: "Effective date",
      description: "Date the engagement begins.",
      required: true,
      visible: true,
    },
    matter: {
      type: "text",
      label: "Matter",
      description: "What the firm is engaged to do, in one line.",
      maxLength: 200,
      required: true,
      visible: true,
    },
    firm: {
      type: "organization",
      label: "Firm",
      description: "Legal name and identifiers of the firm.",
      required: true,
      visible: true,
    },
    firmAddress: {
      type: "address",
      label: "Firm address",
      description: "Principal business address of the firm.",
      required: true,
      visible: true,
    },
    firmContact: {
      type: "person",
      label: "Engagement partner",
      description:
        "The person who signs for the firm. `sealEngagementLetter` reads this field to bind the firm's signer, because core's Signer.person is always a Person and an organization cannot fill it.",
      required: true,
      visible: true,
    },
    client: {
      type: "organization",
      label: "Client",
      description: "Legal name and identifiers of the client.",
      required: true,
      visible: true,
    },
    clientAddress: {
      type: "address",
      label: "Client address",
      description: "Principal business address of the client.",
      required: true,
      visible: true,
    },
    clientContact: {
      type: "person",
      label: "Client signatory",
      description:
        "The person who signs for the client. `sealEngagementLetter` reads this field to bind the client's signer.",
      required: true,
      visible: true,
    },
    scopeOfServices: {
      type: "list",
      label: "Scope of services",
      description: "What the firm will do, one numbered clause per undertaking.",
      minItems: 1,
      required: true,
      visible: true,
      item: {
        type: "fieldset",
        label: "Clause",
        fields: {
          heading: {
            type: "text",
            label: "Heading",
            maxLength: 80,
            required: true,
            visible: true,
          },
          detail: {
            type: "text",
            label: "Detail",
            maxLength: 1200,
            required: true,
            visible: true,
          },
        },
      },
    },
    feeBasis: {
      type: "text",
      label: "Fees",
      description: "How the firm charges for the work, and when it invoices.",
      maxLength: 2000,
      required: true,
      visible: true,
    },
    retainer: {
      type: "money",
      label: "Retainer",
      description: "The sum held on account before work begins.",
      min: 0,
      required: true,
      visible: true,
    },
    term: {
      type: "text",
      label: "Term",
      description: "How long the engagement runs.",
      maxLength: 2000,
      required: true,
      visible: true,
    },
    termination: {
      type: "text",
      label: "Termination",
      description: "How either party ends the engagement, and what survives it.",
      maxLength: 2000,
      required: true,
      visible: true,
    },
    governingLaw: {
      type: "text",
      label: "Governing law",
      description: "The law the engagement is read under, and where disputes are heard.",
      maxLength: 1000,
      required: true,
      visible: true,
    },
  },
  defaultLayer: ENGAGEMENT_LETTER_REACT_LAYER,
  layers: {
    [ENGAGEMENT_LETTER_REACT_LAYER]: {
      kind: "file",
      mimeType: "text/tsx",
      path: ENGAGEMENT_LETTER_REACT_LAYER_PATH,
      title: "Composition",
      description:
        "The React composition this letter is. The path is a pointer: nothing reads the file, and the renderer registered for text/tsx binds the module and seals it.",
      signatures: {
        [ENGAGEMENT_LETTER_SIGNATURE_SLOTS.firm]: {
          party: { role: "firm" },
          type: "signature",
          label: "Firm signature",
          placement: "flow",
        },
        [ENGAGEMENT_LETTER_SIGNATURE_SLOTS.client]: {
          party: { role: "client" },
          type: "signature",
          label: "Client signature",
          placement: "flow",
        },
      },
    },
  },
} as const;

/** The parsed, validated engagement letter. */
export const engagementLetter = para.form(engagementLetterSpec);

/**
 * The same validated artifact as a plain `Form`. Everything that renders or
 * evaluates the letter reads this, so no consumer sees the unparsed spec.
 */
export const engagementLetterForm: Form = engagementLetter.toJSON() as Form;

import type { RuntimeParty } from "@paradoc/types";

import type { DocumentData } from "@paradoc/react";

/**
 * Sample data for the engagement letter.
 *
 * One set, and one is enough. The priced samples carry a short set and an
 * overflow set because their question is where a table breaks, and a table
 * breaks differently at four rows and at sixty. A letter's question is whether
 * a clause of running prose survives the break above it intact and whether the
 * signing blocks stay with the clause they close, and one letter of nine
 * clauses asks both: it runs past the end of the first page, so the plan has a
 * break to place, and it ends in two `Signature` keeps that must not be split.
 *
 * The clause count is asserted in `tests/engagement-letter-artifact.test.ts`,
 * so shortening the letter fails rather than quietly making the second page
 * disappear.
 */

const firm = {
  name: "Ashgrove Rowan",
  legalName: "Ashgrove Rowan LLP",
  domicile: "US",
  entityType: "Limited liability partnership",
  taxId: "26-4471903",
};

const client = {
  name: "Harbor Freight Collective",
  legalName: "Harbor Freight Collective, Inc.",
  domicile: "US",
  entityType: "Corporation",
  taxId: "58-1029384",
};

/** One numbered undertaking. The composition renders each as its own keep. */
interface Clause {
  heading: string;
  detail: string;
}

/** Nine clauses: the letter runs onto a second page, so the plan has a break to place. */
const SCOPE: Clause[] = [
  {
    heading: "Advice on the carrier agreements",
    detail:
      "We will review the twelve carrier agreements you have sent us, report on the terms that differ from your standard form, and tell you which of those differences we think matter. The report will be one document covering all twelve rather than one per agreement.",
  },
  {
    heading: "Renegotiation of the two largest",
    detail:
      "We will act for you in renegotiating the agreements with Vantage Line and Colter Haulage, including drafting the amended terms and attending the meetings at which they are discussed. We will not commit you to anything without your written instruction.",
  },
  {
    heading: "Standard form for new carriers",
    detail:
      "We will draft a standard carrier agreement for you to use with new carriers, together with a short note explaining which clauses you may vary in a negotiation and which you should not.",
  },
  {
    heading: "Regulatory review",
    detail:
      "We will review your operations against the federal and state carrier regulations that apply in the four states you operate in, and report anything that needs to change. This review covers the rules as they stand at the effective date; we will tell you about later changes only if you ask us to keep the review current.",
  },
  {
    heading: "Insurance and indemnity terms",
    detail:
      "We will advise on the insurance and indemnity provisions in each agreement, and on whether the cover you hold answers the liabilities those provisions leave with you. We do not advise on whether the cover is competitively priced, which is a matter for your broker.",
  },
  {
    heading: "Disputes short of proceedings",
    detail:
      "We will advise on disputes with carriers and correspond with them on your behalf. If a dispute goes to proceedings we will tell you before it does, and we will agree separate terms with you for that work rather than doing it under this letter.",
  },
  {
    heading: "Data protection in the driver application",
    detail:
      "We will review the notices and consents in your driver application against the privacy laws of the states your drivers work in, and draft replacements for any that do not answer them.",
  },
  {
    heading: "Reporting",
    detail:
      "We will write to you monthly with the position on each part of this engagement, the fees incurred to date, and anything we need a decision on. You may ask for a report at any other time and we will not charge for producing it.",
  },
  {
    heading: "What is not included",
    detail:
      "We are not engaged to advise on tax, on employment matters, or on the law of any country other than the United States. If you want advice on any of those we will agree it with you separately, in writing, before we start.",
  },
];

/**
 * The sample's data, whose parties carry runtime ids.
 *
 * A document only prints a party, so `DocumentData` asks for the wider `Party`.
 * The seal binds a signer to a party by id, so the sample states that its own
 * parties have one rather than asserting it later.
 */
export interface EngagementLetterData extends DocumentData {
  parties: Record<string, RuntimeParty | RuntimeParty[]>;
}

/** The engagement letter sample: a firm engaged on a haulier's carrier contracts. */
export const engagementLetterData: EngagementLetterData = {
  fields: {
    reference: "AR-2026-0917",
    effectiveDate: "2026-09-15",
    matter: "Carrier contracts and regulatory review",
    firm,
    firmAddress: {
      line1: "310 Congress Avenue",
      line2: "Floor 11",
      locality: "Austin",
      region: "TX",
      postalCode: "78701",
      country: "US",
    },
    firmContact: { name: "Priya Raman", firstName: "Priya", lastName: "Raman", title: "Ms." },
    client,
    clientAddress: {
      line1: "88 Wharf Road",
      locality: "Oakland",
      region: "CA",
      postalCode: "94607",
      country: "US",
    },
    clientContact: { name: "Marisol Vega", firstName: "Marisol", lastName: "Vega", title: "Ms." },
    scopeOfServices: SCOPE,
    feeBasis:
      "We charge by the hour at the rates in the schedule we sent you with this letter, reviewed each January. We invoice monthly in arrears, and payment is due 30 days from the invoice date. We will tell you before the fees on any part of this engagement pass the estimate we gave you for it.",
    retainer: { amount: 15000, currency: "USD" },
    term:
      "The engagement begins on the effective date above and runs until the work described in the scope is finished, or until either party ends it under the clause below.",
    termination:
      "Either party may end this engagement by giving 14 days written notice to the other. You are liable for fees and expenses incurred to the date the notice takes effect. Our duty of confidentiality survives the end of the engagement and has no time limit.",
    governingLaw:
      "This engagement is governed by the law of the State of Texas, and the courts of Travis County have exclusive jurisdiction over any dispute arising from it.",
  },
  parties: {
    firm: { id: "firm-0", ...firm },
    client: { id: "client-0", ...client },
  },
};

import type { Form } from "@paradoc/types";

import { Document } from "@/components/paradoc/document";
import {
  markDocumentRoot,
  useDocument,
  usePage,
  type DocumentData,
  type DocumentTokensInput,
  type FormatOptions,
} from "@paradoc/react";
import { Field } from "@/components/paradoc/field";
import { KeepTogether } from "@/components/paradoc/keep-together";
import { Section } from "@/components/paradoc/section";
import { Signature } from "@/components/paradoc/signature";
import { engagementLetterForm } from "../../artifacts/paradoc/engagement-letter.artifact";

/**
 * The engagement letter, composed from the components.
 *
 * One tree, built from `Document`, `Section`, `Field`, `KeepTogether` and
 * `Signature`, that carries no copy of any label or format. It is the same tree
 * the preview paginates and the PDF renders.
 *
 * **The clauses are keeps, not a table.** A numbered clause is a heading and a
 * paragraph that belong together: split one across a page and the number is on
 * the page above its own words. So each clause is one `KeepTogether`, which is
 * the whole of what makes it unbreakable — nothing here measures anything or
 * decides a page. The list is read from the data rather than written out,
 * because the artifact declares the clauses as a list and a composition that
 * hard-coded ten of them would render nine when a filler supplies nine.
 *
 * **The clause text is read from the context, not from a nested `Field`.** A
 * `Field` is itself a keep, and a keep inside a keep is measured twice: the
 * plan would see the clause and its own paragraph as two overlapping units. So
 * the clause draws the value the same way `Field` does — through the document's
 * formatter, at the path the artifact names — and stays one unit.
 *
 * **There is no `Bundle`.** A letter is one document, and the element walk
 * stops at the first root it finds. One root is what keeps one declaration from
 * becoming two.
 */

/** Stable keep prefix for the numbered clauses. The PDF is hinted with the same ids. */
const CLAUSE_KEEP_PREFIX = "clause";

/**
 * The scope of services, one numbered keep per clause.
 *
 * The wrapper is not a keep, so it has to withdraw on its own, exactly as
 * `Table`'s does: a page holding none of the clauses renders no list at all,
 * because an empty flex child still takes the section's gap and would make the
 * rendered page taller than the flow the plan was measured against.
 */
function Clauses({ path }: { path: string }) {
  const { value, field, format } = useDocument();
  const page = usePage();
  const clauses = value(path);
  const rows = Array.isArray(clauses) ? clauses : [];

  const keepIds = rows.map((_clause, index) => `${CLAUSE_KEEP_PREFIX}:${index}`);
  if (page && !keepIds.some((keepId) => page.keeps.has(keepId))) return null;

  return (
    <div className="flex flex-col gap-3">
      {rows.map((_clause, index) => {
        const headingPath = `${path}.${index}.heading`;
        const detailPath = `${path}.${index}.detail`;
        return (
          <KeepTogether
            key={keepIds[index]}
            keepId={keepIds[index]!}
            className="flex flex-row gap-4"
          >
            <span className="basis-1/12 text-sm font-semibold text-neutral-500">{index + 1}.</span>
            <span className="flex basis-11/12 flex-col gap-1">
              <span data-field-path={headingPath} className="text-sm font-semibold text-neutral-900">
                {format(field(headingPath), value(headingPath), headingPath)}
              </span>
              <span data-field-path={detailPath} className="text-sm leading-relaxed text-neutral-800">
                {format(field(detailPath), value(detailPath), detailPath)}
              </span>
            </span>
          </KeepTogether>
        );
      })}
    </div>
  );
}

export interface EngagementLetterDocumentProps {
  /** The engagement letter data to render. */
  data: DocumentData;
  /** Overrides the artifact, for tests that vary it. */
  artifact?: Form;
  /** How values the serializer registry does not cover are formatted, and which registry (US or EU) covers the rest. */
  format?: FormatOptions;
  /** Tenant branding. See `src/examples/tokens.ts` for a set that changes every token. */
  tokens?: DocumentTokensInput;
}

/**
 * The composed engagement letter.
 *
 * Exported by name and as the module's default. The default is what a React
 * layer binds to when the renderer imports the module the layer's path names,
 * which is the convention a composition module follows.
 */
export function EngagementLetterDocument({
  data,
  artifact = engagementLetterForm,
  format,
  tokens,
}: EngagementLetterDocumentProps) {
  return (
    <Document artifact={artifact} data={data} format={format} tokens={tokens} id="engagement-letter">
      <Section id="masthead" className="flex flex-row justify-between gap-8 border-b border-neutral-800 pb-4">
        <div className="flex basis-1/2 flex-col gap-1">
          <KeepTogether as="span" keepId="title" className="text-lg font-semibold text-neutral-900">
            {artifact.title}
          </KeepTogether>
          <Field path="firm" label={false} className="text-sm text-neutral-700" />
          <Field path="firmAddress" label={false} className="text-sm text-neutral-600" />
        </div>
        <div className="flex basis-1/3 flex-col gap-2">
          <Field path="reference" />
          <Field path="effectiveDate" />
        </div>
      </Section>

      <Section id="client" title="To" className="flex flex-col gap-1">
        <Field path="client" label={false} className="text-sm font-medium text-neutral-900" />
        <Field path="clientContact" label={false} className="text-sm text-neutral-700" />
        <Field path="clientAddress" label={false} className="text-sm text-neutral-600" />
      </Section>

      <Section id="matter" title="Matter">
        <Field path="matter" label={false} className="text-sm leading-relaxed text-neutral-800" />
      </Section>

      <Section id="scope" title="Scope of services">
        <Clauses path="scopeOfServices" />
      </Section>

      <Section id="fees" title="Fees" className="flex flex-col gap-2">
        <Field path="feeBasis" label={false} className="text-sm leading-relaxed text-neutral-800" />
        <Field path="retainer" className="flex flex-col gap-0.5 text-sm text-neutral-800" />
      </Section>

      <Section id="term" title="Term and termination" className="flex flex-col gap-2">
        <Field path="term" label={false} className="text-sm leading-relaxed text-neutral-800" />
        <Field path="termination" label={false} className="text-sm leading-relaxed text-neutral-800" />
      </Section>

      <Section id="governing-law" title="Governing law">
        <Field path="governingLaw" label={false} className="text-sm leading-relaxed text-neutral-800" />
      </Section>

      <Section id="acceptance" title="Agreed" className="flex flex-col gap-4 pt-4">
        <div className="flex flex-row gap-10">
          <Signature party="firm" className="flex basis-1/2 flex-col gap-1" />
          <Signature party="client" className="flex basis-1/2 flex-col gap-1" />
        </div>
      </Section>
    </Document>
  );
}

markDocumentRoot(EngagementLetterDocument);
export default EngagementLetterDocument;
